import axios from 'axios';



const apiReq = axios.create({
  baseURL: 'http://localhost:8085/api',
  headers: {
    'Content-Type': 'application/json',
  },
});


apiReq.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  console.log(token);
  if (token) {
    config.headers['Authorization'] = `Bearer ${token}`;
  }
  return config;
}, (error) => {
  return Promise.reject(error);
});

const WalletService = {
  getWallet: async () => {
    return apiReq.get('/wallet');
  },
  
  getTransactions: async () => {
    return apiReq.get('/wallet/transactions');
  },
  
  deposit: async (amount) => {
    return apiReq.post('/wallet/deposit', { amount });
  },
  
  withdraw: async (amount) => {
    return apiReq.post('/wallet/withdraw', { amount });
  },
  
  transfer: async (recipientWalletNumber, amount) => {
    return apiReq.post('/wallet/transfer', {
      recipientWalletNumber,
      amount,
    });
  },
  
  getTransaction: async (transactionId) => {
    return apiReq.get(`/wallet/transactions/${transactionId}`);
  }
};

export default WalletService;